  {title:'경업금지 약정서',shows:'2년간 동종 업계 취업을 금지했다',caveat:'약정에 대한 보상이 없었다',flaw:'none'},
  {title:'피고 개인 클라우드 내용',shows:'회사 설계 문서 3건이 들어 있었다',caveat:'원고가 피고 계정에 무단 접속해 확인했다',flaw:'illegal'}
