 endings:{claimant:'법원은 약정 위반과 손해를 인정했다. {B|은} 경쟁사를 떠나 대학 강단에 섰다.',respondent:'청구는 받아들여지지 않았다. 원고 회사는 그 뒤 경업금지 약정에 보상 조항을 넣었다.'},
