  {role:'전산 관리자',story:'회사 전산 계정을 관리하는 직원. 계정 공유를 막자고 몇 번이나 보고했다.',says:'결재 계정을 셋이 같이 쓰고 있었어요. 막아야 한다고 했는데 아무도 안 들었습니다',stake:'보안 관리 소홀을 지적받고 있다'}
