  {role:'노무 감정인',story:'법원이 지정한 노무 전문가. 부서별 근무 실태를 조사했다.',says:'프레스와 도장은 인수인계 없이 돌릴 수 없어요. 포장은 사정이 다릅니다',stake:'법원이 지정한 중립 전문가다'}
