   shows:{did:'피고인이 단체로 돌려놓은 돈은 아주 적었다',didnt:'피고인은 옮긴 돈 가운데 상당액을 다시 단체 통장으로 돌려놓았다',reason:'피고인은 돈을 돌려놓다가 마지막 1년에 거의 멈췄다'},
